            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    color = next(v for v in counts if v != bg)

    # The main figure is the largest 4-connected component of the non-background
    # color; isolated interior marks do not determine its frame.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            comps.append(comp)

    main = max(comps, key=len)
    r0, r1 = min(r for r,c in main), max(r for r,c in main)
    c0, c1 = min(c for r,c in main), max(c for r,c in main)
    out = [row[:] for row in grid]

    # Complete the sides of the enclosing rectangular frame.
